-- WP-07 PKG1: load captured Category and Sub type options for the six missing Product Types.
-- TEMPLATE. DRAFT 2026-10-29 IST. NOT APPLIED. Drafted version 20261029191000 (live apply assigns its own).
-- THE DATA BLOCK BELOW IS A PLACEHOLDER WITH ZERO ROWS. It must be replaced by the output of
-- build_pkg1_load.py run on the owner's read-only portal capture CSV. No option label is written by Jarvis.
-- With the placeholder in place this script stops with PKG1_NO_DATA and changes nothing.
-- Marker on every row it creates: source_context.load_batch = context_json.load_batch = 'PKG1_20261029'.
-- Run as ONE transaction (apply_migration or psql -1).

-- 0. Preflight: live reference data still as fingerprinted on 29 Oct 2026 IST.
do $pre$
declare r record;
begin
  for r in
    select * from (values
      ('PRODUCT_CATEGORY','Ayurvedic Proprietary Medicine',83,'3ff21b22d21137e0c07ef802e464eed4'),
      ('PRODUCT_CATEGORY','Siddha Classical Medicine',84,'e300152523987775ca52b9dc4163fe12'),
      ('PRODUCT_SUBTYPE','Ayurvedic Proprietary Medicine',12,'32aa77cee9b8e6e74240d63c666324eb'),
      ('PRODUCT_SUBTYPE','Siddha Classical Medicine',4,'2f99bca691a28f44275e5663d5bae21b'),
      ('PRODUCT_TYPE','',8,'25f803ec6aef2bd89f53a3c076ef3283')) v(d,p,n,fp)
  loop
    if (select count(*) from regulatory.portal_option where domain_code=r.d and parent_external_id=r.p) <> r.n
       or (select md5(string_agg(id||'|'||external_id||'|'||label||'|'||is_active||'|'||coalesce(snapshot_id::text,''), ',' order by id))
             from regulatory.portal_option where domain_code=r.d and parent_external_id=r.p) <> r.fp then
      raise exception 'PKG1_PREFLIGHT_FAILED: % / % changed since fingerprint', r.d, r.p;
    end if;
  end loop;
  if exists (select 1 from regulatory.portal_option where source_context->>'load_batch'='PKG1_20261029') then
    raise exception 'PKG1_ALREADY_LOADED';
  end if;
end $pre$;

create temp table pkg1_capture(
  product_type text not null, domain_code text not null, external_id text not null, label text not null,
  capture_id uuid not null, captured_at timestamptz not null) on commit drop;

