do $chk$
begin
  if (select count(*) from pkg1_capture) = 0 then raise exception 'PKG1_NO_DATA: data block is still the placeholder'; end if;
  if exists (select 1 from pkg1_capture c where not exists (
       select 1 from regulatory.portal_option t where t.portal_code='E_AUSHADHI' and t.domain_code='PRODUCT_TYPE'
         and t.is_active and t.external_id=c.product_type)
     or c.product_type in ('Ayurvedic Proprietary Medicine','Siddha Classical Medicine')) then
    raise exception 'PKG1_BAD_TYPE: only the six missing active Product Types may be loaded'; end if;
  if exists (select 1 from pkg1_capture where domain_code not in ('PRODUCT_CATEGORY','PRODUCT_SUBTYPE')) then
    raise exception 'PKG1_BAD_DOMAIN'; end if;
  if (select count(distinct capture_id) from pkg1_capture) <> 1 then raise exception 'PKG1_ONE_CAPTURE_ONLY'; end if;
end $chk$;

-- 1. Vocabulary snapshots. Several types have byte-identical lists (for example the four Classical sub types), and the table
--    allows one snapshot per (portal, domain, payload hash). So: one snapshot per DISTINCT payload that does not already exist;
--    options below link to the snapshot with the same payload hash (a new one, or the existing identical one).
create temp table pkg1_payload on commit drop as
select product_type, domain_code, min(capture_id::text)::uuid capture_id, min(captured_at) captured_at,
       jsonb_agg(jsonb_build_object('label',label,'external_id',external_id) order by label) payload,
       encode(extensions.digest((jsonb_agg(jsonb_build_object('label',label,'external_id',external_id) order by label))::text,'sha256'),'hex') sha
from pkg1_capture group by 1,2;

with d as (
  select domain_code, sha, min(capture_id::text)::uuid capture_id, min(captured_at) captured_at, (array_agg(payload))[1] payload,
         jsonb_agg(product_type order by product_type) shared_by
  from pkg1_payload p
  where not exists (select 1 from regulatory.portal_vocabulary_snapshot s
                    where s.portal_code='E_AUSHADHI' and s.domain_code=p.domain_code and s.payload_sha256=p.sha)
  group by domain_code, sha)
select 'E_AUSHADHI', d.domain_code,
       jsonb_build_object('capture_id',d.capture_id,'provenance','authenticated_live_portal_capture','captured_at',d.captured_at,
         'source_route','/admin/addproductforlegacy',
         'source_control', case d.domain_code when 'PRODUCT_CATEGORY' then 'DOM:#categoryId' else 'DOM:#subTypeId' end,
         'parent_domain_code','PRODUCT_TYPE','parent_external_id',d.shared_by->>0,'shared_by_product_types',d.shared_by,
         'capture_complete',true,'placeholder_excluded',true,'capture_method','owner_devtools_read_only_snippet',
         'sha256_of','payload_json::text','load_batch','PKG1_20261029'),
       case d.domain_code when 'PRODUCT_CATEGORY' then 'DOM:#categoryId' else 'DOM:#subTypeId' end,
       d.captured_at, d.payload, d.sha,
       'PKG1 owner read-only portal capture; placeholder excluded; no portal mutation.'
from d;

-- 2. Options, linked by parent_domain_code / parent_external_id exactly like the existing 183 rows.
--    Idempotent: skips any row that would collide with either unique index.
                                     first_seen_at, last_seen_at, notes, parent_domain_code, parent_external_id)
select 'E_AUSHADHI', c.domain_code, c.external_id, c.label, s.id,
       jsonb_build_object('capture_id',c.capture_id,'provenance','authenticated_live_portal_capture','captured_at',c.captured_at,
         'source_route','/admin/addproductforlegacy', 'source_control', s.source_endpoint,
         'fill_eligible', (c.label <> '-'), 'capture_complete', true, 'placeholder_excluded', true,
         'parent_domain_code','PRODUCT_TYPE','parent_external_id',c.product_type,'load_batch','PKG1_20261029'),
       true, c.captured_at, c.captured_at,
       case when c.label = '-' then 'Captured domain sentinel. Not a fill target. PKG1_20261029.'
            else 'PKG1_20261029 owner read-only portal capture.' end,
       'PRODUCT_TYPE', c.product_type
from pkg1_capture c
join pkg1_payload pp on pp.product_type=c.product_type and pp.domain_code=c.domain_code
join regulatory.portal_vocabulary_snapshot s
  on s.portal_code='E_AUSHADHI' and s.domain_code=pp.domain_code and s.payload_sha256=pp.sha
where not exists (select 1 from regulatory.portal_option o where o.portal_code='E_AUSHADHI' and o.domain_code=c.domain_code
        and o.parent_domain_code='PRODUCT_TYPE' and o.parent_external_id=c.product_type
        and (o.external_id=c.external_id or lower(btrim(o.label))=lower(btrim(c.label))));

-- 3. In-transaction check: every captured row loaded, nothing else touched.
do $post$
begin
  if (select count(*) from regulatory.portal_option where source_context->>'load_batch'='PKG1_20261029')
     <> (select count(*) from pkg1_capture) then raise exception 'PKG1_ROW_COUNT_MISMATCH'; end if;
  if (select count(*) from regulatory.portal_option where domain_code in ('PRODUCT_CATEGORY','PRODUCT_SUBTYPE')
        and parent_external_id in ('Ayurvedic Proprietary Medicine','Siddha Classical Medicine')) <> 183 then
    raise exception 'PKG1_EXISTING_ROWS_CHANGED'; end if;
end $post$;
